import numpy as np, time, copy
from reference import Task
from scipy.sparse.linalg import eigs
import random

def pass_rate(tol=1e-8, maxiter=None, ncv=20):
    task=Task(); passes=0; fails=0
    for seed in range(50):
        prob=task.generate_problem(n=300, random_seed=seed)
        A=prob['matrix']; N=A.shape[0]; k=prob['k']
        try:
            vals, vecs = eigs(A,k=k,v0=np.ones(N),tol=tol,ncv=ncv,maxiter=maxiter)
        except Exception:
            fails+=1
            continue
        pairs=list(zip(vals, vecs.T)); pairs.sort(key=lambda p:-abs(p[0])); cand=[p[1] for p in pairs]
        # expected via reference method
        exp=Task().solve(prob)
        good=True
        for idx,(c,e) in enumerate(zip(cand, exp)):
            sim=abs(np.dot(np.conj(e)/np.linalg.norm(e), c/np.linalg.norm(c)))
            if not np.isclose(sim,1.0,atol=1e-6):
                good=False; break
        if good:
            passes+=1
        else:
            fails+=1
    return passes, fails

for tol in [0,1e-12,1e-11,1e-10,1e-9,1e-8,1e-7,1e-6]:
    passes,fails=pass_rate(tol=tol,ncv=20,maxiter=None)
    print('tol',tol,'passes',passes,'fails',fails)
